import{z as d,x as m,o as t,c as B,q as l,j as i,D as n,d as r,s,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"算术编码","description":"","frontmatter":{"title":"算术编码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arithmetic-coding.md","filePath":"cs/arithmetic-coding.md","lastUpdated":1791063341000}'),E={name:"cs/arithmetic-coding.md"};function A(f,a,h,u,C,c){const o=m("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="算术编码" tabindex="-1">算术编码 <a class="header-anchor" href="#算术编码" aria-label="Permalink to &quot;算术编码&quot;">​</a></h1><div class="epigraph"><p>把整条消息映到 $[0,1)$ 里一段长度为 $p(x^n)$ 的区间，再输出区间里的一个二进制小数；码长可以是分数比特，逼近 $H$ 不必等到巨型符号表。</p><footer>—— 据 Rissanen；Witten, Neal and Cleary, 1987；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/huffman-coding">Huffman</a> 的码长是整数，单符号离 \\(H\\) 可差 1。缺口是<strong>算术编码</strong>：用区间套表示消息，输出长度 \\(\\approx -\\log p(x^n)\\)。不重做 Huffman 树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>按 \\(p\\) 把 \\([0,1)\\) 划成子区间，读一个符号就进入对应子区间，长度乘 \\(p(a)\\)。最终区间长度 \\(=p(x^n)\\)，其中任选一点的二进制展开约 \\(-\\log p(x^n)\\) 比特即可唯一标识（与相邻区间分开）。期望码长 \\(\\to H\\)。自适应：边读边更新 \\(p\\)，不必事先扫描。</p><p><span class="marginnote">直觉类比：整条消息像在 \\([0,1)\\) 这把尺上不断对折出小段——每读一个符号就钻进按概率划出的子段；概率越小的符号段越窄，最后那段越窄，指认它所需的小数位就越多，这正是「罕见消息更长」的来源。</span></p><p>实现用整数缩放代替无限精度，本课要区间图像，不写进位细节。</p><h3 id="不是「把符号当数字相加」" tabindex="-1">不是「把符号当数字相加」 <a class="header-anchor" href="#不是「把符号当数字相加」" aria-label="Permalink to &quot;不是「把符号当数字相加」&quot;">​</a></h3><p>名字里的 arithmetic 是区间端点的加减乘。与后课数论模运算无关。也不要把浮点误差当成定理的一部分——定理在精确实数上，工程用整数。</p><p><span class="marginnote">Rissanen 算术编码；Witten–Neal–Cleary 的 CACM 实现。Cover–Thomas 把它当 Shannon 码的极限。专利史曾影响部署，本课不谈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三步套区间的数轴。对比 Huffman：同一 \\(p\\)，算术对整句记账，Huffman 对每个符号付整比特。指出：译码端必须共享同一 \\(p\\) 或同一自适应规则，否则区间对不齐——与密码无关，是模型约定。</p>',12)),(t(),i(p,null,{default:n(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%20x%5En%22%5D%20--%3E%20INT%5B%22%E5%A5%97%E5%8C%BA%E9%97%B4%20%E9%95%BF%E5%BA%A6%20p(x%5En)%22%5D%0A%20%20INT%20--%3E%20BIN%5B%22%E8%BE%93%E5%87%BA%E5%8C%BA%E9%97%B4%E5%86%85%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%0A%20%20BIN%20--%3E%20LEN%5B%22%E9%95%BF%E5%BA%A6%20%E2%89%88%20-log%20p%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"信源编码定理的可达半边，算术给出建设性、无需 \\(n\\) 元组爆炸。LZ 下一课连 \\(p\\) 都不显式要，用字典。本课仍假设模型（静态或自适应计数）。",-1)),a[5]||(a[5]=e("p",null,"前缀：输出可以设计成前缀码（加结束标记）。流式：区间端点的高位稳定即可先发出。",-1)),a[6]||(a[6]=e("p",null,"发送端不必等整句结束：一旦区间高位稳定即可输出。结束符或显式长度防止译码多读。自适应计数等价于「边走边改划分」；\\(p\\) 估计不足时 \\(D(p\\|\\hat p)\\) 就是多付的比特，KL 课再写。与模运算无关：端点是有理数缩放，不是 \\(\\mathbb{Z}/n\\mathbb{Z}\\)。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},'数字实例：取 \\(p(a)=0.5\\)、\\(p(b)=0.25\\)、\\(p(c)=0.25\\)，编码 "abc" 的区间依次是 \\([0,1)\\to[0,0.5)\\to[0.25,0.375)\\to[0.34375,0.375)\\)，宽度 \\(0.03125=2^{-5}\\)，输出区间内任一点约 5 比特。若宽度是 \\(0.04\\)，\\(-\\log_2 0.04\\approx 4.6\\)——分数比特正是算术对 Huffman 的赢面。')],-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为编码端换了更准的概率模型，解码端拿旧模型也能凑合译。实际上两边划分必须逐符号一致，差一步区间就错位、后面全部乱码——这是约定对齐问题，不是加密也不是校验。")],-1)),(t(),i(p,null,{default:n(()=>[s(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20S0%5B%22%E5%8C%BA%E9%97%B4%20%5B0%2C1)%22%5D%20--%3E%7C%22%E8%AF%BB%20a%3A%20p%3D0.5%22%7C%20S1%5B%22%5B0%2C%200.5)%22%5D%0A%20%20S1%20--%3E%7C%22%E8%AF%BB%20b%3A%20p%3D0.25%22%7C%20S2%5B%22%5B0.25%2C%200.375)%22%5D%0A%20%20S2%20--%3E%7C%22%E8%AF%BB%20c%3A%20p%3D0.25%22%7C%20S3%5B%22%5B0.34375%2C%200.375)%22%5D%0A%20%20S3%20--%3E%20OUT%5B%22%E5%AE%BD%E5%BA%A6%200.03125%2C%20%E8%BE%93%E5%87%BA%E5%8C%BA%E9%97%B4%E5%86%85%E7%BA%A6%205%20%E6%AF%94%E7%89%B9%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写整数实现的 renormalization 全文，不引入 ANS。不把大模型的 token 概率请进来当主例子——对象仍是有限字母表信源。后课默认：分数比特码长用区间。下一课无模型字典：LZ77/78。</p><p>区间长度 \\(p(x^n)\\) 把整句的 \\(-\\log p\\) 一次付清，所以不必等 \\(n\\) 元组 Huffman 表。编解码模型不一致则区间错位，这是同步约定，不是保密。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>消息 \\(\\leftrightarrow\\) 长度 \\(p(x^n)\\) 的区间；输出其二进制。</li><li>期望码长逼近 \\(H\\)，打破单符号整数限制。</li><li>编解码必须共享模型。</li><li>出处：Rissanen；Witten, Neal and Cleary, 1987；Cover and Thomas。</li></ul>',5))])}const x=d(E,[["render",A]]);export{g as __pageData,x as default};
